using Autodesk.Revit.ApplicationServices;using Autodesk.Revit.DB;using SAUDICO.Federate.Core.Interfaces;using SAUDICO.Federate.Core.Models;using SAUDICO.Federate.Shared;namespace SAUDICO.Federate.ACC;
public sealed class FileDocumentOpener:IDocumentOpener { public Document Open(ModelInfo m,Application app){var op=new OpenOptions();if(m.Type==ModelType.Central)op.DetachFromCentralOption=DetachFromCentralOption.DetachAndPreserveWorksets;if(m.Type==ModelType.Central||m.Type==ModelType.WorksharedLocal)op.SetOpenWorksetsConfiguration(new WorksetConfiguration(WorksetConfigurationOption.OpenAllWorksets));return app.OpenDocumentFile(ModelPathUtils.ConvertUserVisiblePathToModelPath(m.FilePath),op);} }
